/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.submit = async function () {
    /* sdd-asis-lifecycle:begin submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "featurePersonSearchList");
    $c.util.getComponent("ipt_comName").setValue(encodeURI($c.util.getComponent('ipt_comName').getValue()));
    $c.util.getComponent("ipt_name").setValue(encodeURI($c.util.getComponent('ipt_name').getValue()));
    $c.util.getComponent("dma_submitReq").set("beforeName", encodeURI($c.util.getComponent("dma_submitReq").get("beforeName")));
    if ($c.num.isNumber($c.util.getComponent('ipt_comCode').getValue()) && $c.util.getComponent('ipt_comCode').getValue().length == 6) {
        $c.util.getComponent("ipt_comCode").setValue("A" + $c.util.getComponent('ipt_comCode').getValue());
    }
    if ((document.form || { elements: [] }).regcncl[1].checked) {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    } else {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    }
    await scwin.tx_submit();

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchPerson
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchPerson = async function () {
    /* sdd-asis-lifecycle:begin searchPerson — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let chgList;
    $c.util.getComponent("ipt_name").setValue(encodeURI($c.util.getComponent('ipt_name').getValue()));
    const strOptions = "width=430, height=300, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    chgList = $c.win.openPopup("", String((typeof strOptions !== 'undefined' ? strOptions : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "chgList", width: "430", height: "300", scrollbars: true, resizable: false, type: "pageFramePopup" }, { id: '' }) : { id: "chgList", width: "430", height: "300", scrollbars: true, resizable: false, type: "pageFramePopup" }), {});
    (document.form2 || { elements: [] }).target = "chgList";
    await scwin.tx_searchPerson();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param searchValue
 * @returns
 * @hidden N
*/
scwin.searchCode = function (searchValue) {
    /* sdd-asis-lifecycle:begin searchCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let iCount = 0;
    arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jcode.substring(0, searchValue.length)) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                if (regcncl === "1") {
                    arrCode[iCount] = jr[j].jcode;
                    arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        arrCode[iCount] = jr[j].jcode;
                        arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    setSelectBox();
    /* sdd-asis-lifecycle:end */
};
